arguments.command:
cat >> glom/core.py <<'EOF'

# New specifier classes added for release
class Auto(object):
    """Placeholder specifier that returns the target unchanged."""
    def __init__(self):
        pass
    def glomit(self, target, scope):
        return target
    def __repr__(self):
        return 'Auto()'

class Fill(object):
    """Return the target if it is truthy, otherwise return the provided value."""
    def __init__(self, value=None):
        self.value = value
    def glomit(self, target, scope):
        return target if target else self.value
    def __repr__(self):
        return f'Fill({self.value!r})'

class Iter(object):
    """Iterate over the target and apply a subspec to each item."""
    def __init__(self, spec):
        self.spec = spec
    def glomit(self, target, scope):
        try:
            iterator = scope[glom].__self__ if hasattr(scope[glom], '__self__') else None
        except Exception:
            iterator = None
        # Use the generic iterator from scope
        iterate = scope.get('iterate', None)
        if iterate is None:
            iterate = lambda t: iter(t)
        try:
            it = iterate(target)
        except Exception:
            return target
        return [scope[glom](t, self.spec, scope.new_child({Path: scope[Path] + [i]})) for i, t in enumerate(it)]
    def __repr__(self):
        return f'Iter({self.spec!r})'

class Let(object):
    """Bind a variable to a value within a spec."""
    def __init__(self, name, val, spec):
        self.name = name
        self.val = val
        self.spec = spec
    def glomit(self, target, scope):
        new_scope = scope.copy()
        new_scope[self.name] = scope[glom](target, self.val, scope)
        return scope[glom](target, self.spec, new_scope)
    def __repr__(self):
        return f'Let({self.name!r}, {self.val!r}, {self.spec!r})'

# ROOT is an alias for the root Path
ROOT = Path()

# Invoke specifier: call a function with given arguments, exposing constants
class Invoke(object):
    def __init__(self, func, *args, **kwargs):
        if not callable(func) and not isinstance(func, TType):
            raise TypeError('expected func to be callable or T expression')
        self.func = func
        self.constants = (args, kwargs)
    def glomit(self, target, scope):
        def _eval(val):
            if isinstance(val, Spec) or isinstance(val, TType):
                return scope[glom](target, val, scope)
            return val
        args, kwargs = self.constants
        eval_args = [_eval(a) for a in args]
        eval_kwargs = {k: _eval(v) for k, v in kwargs.items()}
        return _eval(self.func)(*eval_args, **eval_kwargs)
    def __repr__(self):
        args, kwargs = self.constants
        return f'Invoke({self.func!r}, args={args!r}, kwargs={kwargs!r})'
EOF
